NAMES = {0x22: "ReadDataByIdentifier", 0x27: "SecurityAccess"}
NRC = {0x31: "requestOutOfRange", 0x33: "securityAccessDenied"}

def single_frame(uds, pad=0xAA):   # 상위 4비트 0 = 단일 프레임, 하위 4비트 = 길이
    assert len(uds) <= 7
    return bytes([len(uds)]) + uds + bytes([pad] * (7 - len(uds)))

def read(frame):
    n = frame[0] & 0x0F; uds = frame[1:1 + n]
    if uds[0] == 0x7F:
        return "거절: " + NAMES[uds[1]] + " → " + NRC[uds[2]]
    return "성공: " + NAMES[uds[0] - 0x40] + " " + uds[1:].hex(" ")

print(single_frame(bytes([0x22, 0xF1, 0x90])).hex(" "))
print(read(bytes.fromhex("03 7F 22 31 AA AA AA AA")))
print(read(bytes.fromhex("06 67 01 3A 9C 51 07 AA")))
print(read(bytes.fromhex("03 7F 27 33 AA AA AA AA")))
